def N(label,answer,unit,why,tol=None):
 return dict(label=label,type='numeric',answer=answer,unit=unit,tolerance=max(abs(answer)*.008,1e-10) if tol is None else tol,explanation=why)
def C(label,answer,b,c,why):
 return dict(label=label,type='choice',answer=answer,options=[answer,b,c],explanation=why)
def add(n,parts,reason,check,page=None,kind='problems',assumptions=None,scope=None):
 if page is None:page=21 if n<=6 else 22 if n<=19 else 23 if n<=33 else 24 if n<=48 else 25 if n<=62 else 26 if n<=72 else 27
 r=dict(id=f'physics-chapter-14-{kind}-{n}',parts=parts,reasoning=reason+' Verification: '+check,sourcePages=[page],assumptions=assumptions or ['Use g=9.80 m/s²; fresh-water density is 1000 kg/m³ unless stated otherwise.'])
 if scope:r['scope']=scope
 out.append(r)
